const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-hub-signature-256'] || '';
const info = {
  jsonKeys: Object.keys(item.json),
  binaryKeys: Object.keys(item.binary || {}),
  bodyIsObject: typeof item.json.body === 'object',
  bodyKeys: (item.json.body && typeof item.json.body === 'object') ? Object.keys(item.json.body) : null,
  sigHeaderPresent: !!sig
};

let raw = null;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  info.rawLength = raw.length;
} catch (e) {
  info.rawError = String(e.message || e);
}

let crypto = null;
try {
  crypto = require('crypto');
  info.cryptoRequire = 'ok';
} catch (e) {
  info.cryptoRequire = 'failed: ' + String(e.message || e);
}

if (raw && crypto) {
  const expected = 'sha256=' + crypto.createHmac('sha256', 'testsecret').update(raw).digest('hex');
  info.signatureMatch = expected === sig;
}

return [{ json: info }];
